export function createOfflineQueue({
  storage,
  send,
  key = "queue:v1",
  maxAttempts = 5,
}) {
  let items = [];

  try {
    const stored = storage.getItem(key);

    if (stored !== null) {
      const parsed = JSON.parse(stored);

      if (Array.isArray(parsed)) {
        items = parsed;
      }
    }
  } catch {
    items = [];
  }

  let inFlight = null;
  let runningFlush = null;

  function persist() {
    storage.setItem(key, JSON.stringify(items));
  }

  function enqueue(action) {
    for (const item of items) {
      if (item.id === action.id) {
        return undefined;
      }
    }

    const dedupeKey = action.dedupeKey;

    if (dedupeKey !== undefined) {
      for (const item of items) {
        if (item !== inFlight && item.dedupeKey === dedupeKey) {
          item.type = action.type;
          item.payload = action.payload;
          item.attempts = 0;
          persist();
          return undefined;
        }
      }
    }

    items.push({
      id: action.id,
      type: action.type,
      payload: action.payload,
      dedupeKey,
      attempts: 0,
    });

    persist();
    return undefined;
  }

  function flush() {
    if (runningFlush !== null) {
      return runningFlush;
    }

    let resolveFlush;
    let rejectFlush;

    const promise = new Promise((resolve, reject) => {
      resolveFlush = resolve;
      rejectFlush = reject;
    });

    runningFlush = promise;

    const finish = (result) => {
      if (runningFlush === promise) {
        runningFlush = null;
      }
      resolveFlush(result);
    };

    const fail = (error) => {
      if (runningFlush === promise) {
        runningFlush = null;
      }
      rejectFlush(error);
    };

    void (async () => {
      const sent = [];
      const failed = [];

      try {
        while (items.length > 0) {
          const item = items[0];
          let outcome = "retryable";

          inFlight = item;

          try {
            const response = await send({
              id: item.id,
              type: item.type,
              payload: item.payload,
            });

            let ok;
            if (response !== null && response !== undefined) {
              ok = response.ok;
            }

            if (ok === true) {
              outcome = "success";
            } else if (ok === false && response.retryable === false) {
              outcome = "permanent";
            }
          } catch {
            outcome = "retryable";
          } finally {
            inFlight = null;
          }

          if (outcome === "success") {
            items.shift();
            persist();
            sent.push(item.id);
            continue;
          }

          if (outcome === "permanent") {
            items.shift();
            persist();
            failed.push({ id: item.id, reason: "rejected" });
            continue;
          }

          const previousAttempts = Number.isFinite(item.attempts)
            ? item.attempts
            : 0;

          item.attempts = previousAttempts + 1;
          persist();

          if (item.attempts >= maxAttempts) {
            items.shift();
            persist();
            failed.push({ id: item.id, reason: "max-attempts" });
          }

          finish({
            sent,
            failed,
            remaining: items.length,
          });
          return;
        }

        finish({
          sent,
          failed,
          remaining: items.length,
        });
      } catch (error) {
        inFlight = null;
        fail(error);
      }
    })();

    return promise;
  }

  function size() {
    return items.length;
  }

  function peek() {
    return items.map((item) => ({
      id: item.id,
      type: item.type,
      payload: item.payload,
      dedupeKey: item.dedupeKey,
      attempts: item.attempts,
    }));
  }

  return {
    enqueue,
    flush,
    size,
    peek,
  };
}
